CANDIDATES_PER_MENTION = 3
CLAIMS_PER_CANDIDATE = 3
EVIDENCE_CHARS = 200
KNOWN_NAMES = 15
KNOWN_PREDICATES = 15
LINK_MENTIONS_PER_CALL = 15
OPEN_TASKS = 8
SIMILAR_NOTES = 5
SUMMARY_CHARS = 240
TOPICS = 50
def clip(text, limit):
